import React from 'react';
import CustomerDetailClient from './CustomerDetailClient';

export default function Page({ params }: { params: { id: string } }) {
  return <CustomerDetailClient id={params.id} />;
}

// For static export compatibility, read customer IDs from the active DB
// and return them so Next can statically export those pages.
export async function generateStaticParams() {
  try {
    // Import backend database-manager to access the active DB.
    // This code runs on the server during build/dev, so CommonJS require is safe.
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const databaseManager = require('../../../../../src-backend/database-manager');
    const db = databaseManager.getActiveDb();

    const ids = await new Promise<any[]>((resolve, reject) => {
      db.all('SELECT id FROM customers LIMIT 1000', [], (err: any, rows: any[]) => {
        if (err) return reject(err);
        resolve(rows.map((r: any) => ({ id: String(r.id) })));
      });
    });

    return ids;
  } catch (err: any) {
    // If DB not available during export/dev, return empty to avoid build failure.
    console.warn('generateStaticParams: could not read customers from DB', String(err));
    return [];
  }
}
